<?php require_once '../includes/bootstrap.php';if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: cart.php');exit;}verify_csrf();$id=(string)($_POST['id']??'');$qty=filter_var($_POST['quantity']??1,FILTER_VALIDATE_INT);if(isset($_SESSION['cart'][$id])){if($qty===false||$qty<1)$_SESSION['cart'][$id]['quantity']=1;else $_SESSION['cart'][$id]['quantity']=min(99,$qty);}header('Location: cart.php');exit;
